#!/usr/bin/env node
/*
 * generate-espeak-demos.mjs — render the demos.html audio for the local eSpeak NG voices.
 *
 * The server-side voices on that page are generated by eas-tts/generate_demos.py against
 * the Wags' Puzzle Space TTS endpoint. eSpeak runs locally, so it gets its own renderer,
 * but it speaks the same sentence template so the demos stay comparable.
 *
 * Output: assets/demo_files/<demoName> Demo.wav — 22050 Hz mono 16-bit, eSpeak's native
 * rate, matching the convention that every demo keeps its engine's own sample rate.
 *
 * Requires espeak-ng.eas.data; run tools/build-espeak-data.mjs first if it is missing.
 *
 * Usage:
 *   node tools/generate-espeak-demos.mjs
 *   node tools/generate-espeak-demos.mjs --force   (overwrite existing files)
 */

import { readFileSync, writeFileSync, existsSync } from 'node:fs';
import { dirname, join, resolve } from 'node:path';
import { fileURLToPath, pathToFileURL } from 'node:url';
import vm from 'node:vm';

const HERE = dirname(fileURLToPath(import.meta.url));
const ESPEAK_DIR = resolve(HERE, '..', 'assets', 'wasm_tts_voices', 'espeak');
const DEMO_DIR = resolve(HERE, '..', 'assets', 'demo_files');

const SAMPLE_TEXT = (voice) =>
    `This is a demonstration of ${voice} using Wags's Emergency Alert System Text To Speech A P I.`;

/* demoName is the file basename demos.html asks for; spokenName is the same voice written
 * so eSpeak reads it correctly ("U S", not "us"). */
const DEMOS = [
    { voice: 'en-us',         demoName: 'eSpeak English US',           spokenName: 'e Speak, English U S' },
    { voice: 'en-us+m3',      demoName: 'eSpeak English US Male 3',    spokenName: 'e Speak, English U S, male three' },
    { voice: 'en-us+f2',      demoName: 'eSpeak English US Female 2',  spokenName: 'e Speak, English U S, female two' },
    { voice: 'en-us+whisper', demoName: 'eSpeak English US Whisper',   spokenName: 'e Speak, English U S, whisper' },
    { voice: 'en-us+croak',   demoName: 'eSpeak English US Croak',     spokenName: 'e Speak, English U S, croak' },
    { voice: 'en-us+klatt',   demoName: 'eSpeak English US Klatt',     spokenName: 'e Speak, English U S, Klatt formant' },
    { voice: 'en',            demoName: 'eSpeak English UK',           spokenName: 'e Speak, English U K' },
    { voice: 'es-419',        demoName: 'eSpeak Spanish',              spokenName: 'e Speak, Spanish' },
    { voice: 'fr',            demoName: 'eSpeak French',               spokenName: 'e Speak, French' },
];

function writeWav(path, pcm16, sampleRate) {
    const dataBytes = pcm16.length * 2;
    const buf = Buffer.alloc(44 + dataBytes);
    buf.write('RIFF', 0);
    buf.writeUInt32LE(36 + dataBytes, 4);
    buf.write('WAVE', 8);
    buf.write('fmt ', 12);
    buf.writeUInt32LE(16, 16);
    buf.writeUInt16LE(1, 20);
    buf.writeUInt16LE(1, 22);
    buf.writeUInt32LE(sampleRate, 24);
    buf.writeUInt32LE(sampleRate * 2, 28);
    buf.writeUInt16LE(2, 32);
    buf.writeUInt16LE(16, 34);
    buf.write('data', 36);
    buf.writeUInt32LE(dataBytes, 40);
    for (let i = 0; i < pcm16.length; i++) buf.writeInt16LE(pcm16[i], 44 + i * 2);
    writeFileSync(path, buf);
}

async function loadEngine() {
    const loader = join(ESPEAK_DIR, 'espeak-ng.eas.js');
    const data = join(ESPEAK_DIR, 'espeak-ng.eas.data');
    for (const file of [loader, data]) {
        if (!existsSync(file)) {
            throw new Error(`${file} is missing — run "node tools/build-espeak-data.mjs" first.`);
        }
    }

    /* The loader's Node branch is the one path we do not want: it would read the data
     * package off disk itself and pull in node:module. Presenting process.type as
     * "renderer" sends it down the browser path, and the bytes are handed over directly. */
    process.type = 'renderer';
    globalThis.__espeakNgScriptUrl = pathToFileURL(loader).href;
    vm.runInThisContext(readFileSync(loader, 'utf8'), { filename: loader });

    const wasmBinary = new Uint8Array(readFileSync(join(ESPEAK_DIR, 'espeak-ng.wasm')));
    const dataBuf = readFileSync(data);
    const dataAb = dataBuf.buffer.slice(dataBuf.byteOffset, dataBuf.byteOffset + dataBuf.byteLength);

    const module = await globalThis.EspeakNgModule({
        instantiateWasm: (imports, successCallback) => {
            WebAssembly.instantiate(wasmBinary, imports).then((r) => successCallback(r.instance));
            return {};
        },
        getPreloadedPackage: () => dataAb,
        locateFile: (file) => join(ESPEAK_DIR, file),
        print: () => {},
        printErr: () => {},
    });

    const sampleRate = module.ccall('espeakng_init', 'number', ['string'], ['/']);
    if (sampleRate <= 0) throw new Error('espeakng_init failed');
    return { module, sampleRate };
}

async function main() {
    const force = process.argv.includes('--force');
    const { module, sampleRate } = await loadEngine();

    let written = 0;
    let skipped = 0;
    for (const demo of DEMOS) {
        const path = join(DEMO_DIR, `${demo.demoName} Demo.wav`);
        if (!force && existsSync(path)) {
            console.log(`skip   ${demo.demoName} (exists)`);
            skipped++;
            continue;
        }
        if (module.ccall('espeakng_set_voice', 'number', ['string'], [demo.voice]) !== 0) {
            throw new Error(`voice "${demo.voice}" is not in the data package`);
        }
        module.ccall('espeakng_set_rate', 'number', ['number'], [175]);
        module.ccall('espeakng_set_pitch', 'number', ['number'], [50]);

        const text = SAMPLE_TEXT(demo.spokenName);
        const n = module.ccall('espeakng_synthesize', 'number', ['string'], [text]);
        if (n <= 0) throw new Error(`synthesis returned ${n} for ${demo.voice}`);

        const ptr = module.ccall('espeakng_pcm', 'number', [], []);
        const pcm = module.HEAP16.slice(ptr >> 1, (ptr >> 1) + n);
        writeWav(path, pcm, sampleRate);
        console.log(`write  ${demo.demoName} Demo.wav  ${(n / sampleRate).toFixed(2)}s  voice=${demo.voice}`);
        written++;
    }

    console.log(`\n${written} written, ${skipped} skipped.`);
}

main().catch((err) => {
    console.error(err.message || err);
    process.exit(1);
});
